```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <vector>
using namespace std;

string naOsemkowy(int n) {
    if (n == 0) return "0";
    string wynik = "";
    while (n > 0) {
        wynik = char('0' + n % 8) + wynik;
        n /= 8;
    }
    return wynik;
}

int sumaCyfr(const string& s) {
    int suma = 0;
    for (char c : s) suma += c - '0';
    return suma;
}

int main() {
    ifstream plik("dane.txt");
    int n;
    vector<int> liczby;
    vector<string> osemkowe;
    while (plik >> n) {
        liczby.push_back(n);
        osemkowe.push_back(naOsemkowy(n));
    }

    cout << "a) Reprezentacja osemkowa:" << endl;
    for (int i = 0; i < (int)liczby.size(); i++) {
        cout << liczby[i] << " -> " << osemkowe[i] << endl;
    }

    cout << endl << "b) Suma cyfr osemkowych:" << endl;
    int maxSuma = -1, maxIdx = -1;
    for (int i = 0; i < (int)liczby.size(); i++) {
        int s = sumaCyfr(osemkowe[i]);
        cout << liczby[i] << " (" << osemkowe[i] << "): suma = " << s << endl;
        if (s > maxSuma) {
            maxSuma = s;
            maxIdx = i;
        }
    }
    cout << "Najwieksza suma cyfr osemkowych: " << liczby[maxIdx] << " (" << osemkowe[maxIdx] << "), suma = " << maxSuma << endl;
    return 0;
}
```

**Wyjasnienie**: Konwersja na system osemkowy = wielokrotne modulo 8 z budowa stringa od lewej. Suma cyfr osemkowych to suma wartosci znakow.

Weryfikacja:
- 255: 255/8=31 r7, 31/8=3 r7, 3/8=0 r3 -> 377, suma=17
- 100: 100/8=12 r4, 12/8=1 r4, 1/8=0 r1 -> 144, suma=9
- 64: 64/8=8 r0, 8/8=1 r0, 1/8=0 r1 -> 100, suma=1
- 511: 511/8=63 r7, 63/8=7 r7, 7/8=0 r7 -> 777, suma=21
